import os
from typing import Any, Dict, Optional

import requests


class ImageSafetyChecker:
    def __init__(self, api_key: Optional[str] = None) -> None:
        self.api_key = api_key or os.environ["SIGHTENGINE_API_USER"]
        self.api_secret = os.environ["SIGHTENGINE_API_SECRET"]
        self.endpoint = "https://api.sightengine.com/1.0/check.json"

    def check_image(
        self,
        image_path: Optional[str] = None,
        image_url: Optional[str] = None,
    ) -> Dict[str, Any]:
        if not image_path and not image_url:
            raise ValueError("Either image_path or image_url must be provided.")
        if image_path and image_url:
            raise ValueError("Provide only one of image_path or image_url.")

        data = {
            "api_user": self.api_key,
            "api_secret": self.api_secret,
            "models": "nudity-2.1,weapon,recreational_drug,medical,tobacco,gore-2.0,violence,self-harm,gambling",
        }

        files = None
        if image_path:
            files = {"media": open(image_path, "rb")}
        else:
            data["url"] = image_url

        try:
            response = requests.post(self.endpoint, data=data, files=files, timeout=60)
            response.raise_for_status()
            result = response.json()
        finally:
            if files and "media" in files:
                files["media"].close()

        return self._normalize_result(result)

    def _normalize_result(self, result: Dict[str, Any]) -> Dict[str, Any]:
        def get_nested(d: Dict[str, Any], *keys: str, default: float = 0.0) -> float:
            cur: Any = d
            for key in keys:
                if not isinstance(cur, dict) or key not in cur:
                    return default
                cur = cur[key]
            return float(cur) if isinstance(cur, (int, float)) else default

        categories = {
            "nudity": max(
                get_nested(result, "nudity", "sexual_activity"),
                get_nested(result, "nudity", "sexual_display"),
                get_nested(result, "nudity", "erotica"),
                get_nested(result, "nudity", "very_suggestive"),
                get_nested(result, "nudity", "suggestive"),
            ),
            "weapon": get_nested(result, "weapon", "classes", "firearm"),
            "drugs": max(
                get_nested(result, "recreational_drug", "prob"),
                get_nested(result, "tobacco", "prob"),
            ),
            "gore": get_nested(result, "gore", "prob"),
            "violence": get_nested(result, "violence", "prob"),
            "self_harm": get_nested(result, "self-harm", "prob"),
            "medical": get_nested(result, "medical", "prob"),
            "gambling": get_nested(result, "gambling", "prob"),
        }

        max_category = max(categories, key=categories.get)
        max_score = categories[max_category]

        return {
            "provider": "Sightengine",
            "unsafe": max_score >= 0.5,
            "top_category": max_category,
            "top_score": max_score,
            "scores": categories,
            "raw": result,
        }
